from typing import Any, Callable, Dict, Type, get_type_hints
from functools import wraps

def enforce_types(type_map: Dict[str, Type[Any]]) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    """Build a decorator that enforces argument types for a function.

    Args:
        type_map: Mapping from argument name to expected type.

    Returns:
        A decorator that wraps the function and rejects mismatched arguments.

    Examples:
        >>> @enforce_types({"x": int, "y": int})
        ... def add(x, y):
        ...     return x + y
        >>> add(1, 2)
        3
        >>> add(1, "2")
        Traceback (most recent call last):
        ...
        TypeError: argument 'y' must be int, got str
    """
    def decorator(func: Callable[..., Any]) -> Callable[..., Any]:
        @wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            hints = get_type_hints(func)
            for arg_name, expected in type_map.items():
                if arg_name in kwargs:
                    value = kwargs[arg_name]
                else:
                    try:
                        value = _bind_arg(func, arg_name, args)
                    except IndexError:
                        continue
                if not isinstance(value, expected):
                    raise TypeError(
                        f"argument {arg_name!r} must be {expected.__name__}, "
                        f"got {type(value).__name__}"
                    )
            return func(*args, **kwargs)
        return wrapper
    return decorator

def _bind_arg(func: Callable[..., Any], name: str, args: tuple) -> Any:
    import inspect
    sig = inspect.signature(func)
    params = [p for p in sig.parameters.values() if p.kind in (p.POSITIONAL_OR_KEYWORD, p.POSITIONAL_ONLY)]
    for i, p in enumerate(params):
        if p.name == name:
            return args[i]
    raise IndexError(name)

from typing import Any, Dict


def coerce_int(value: Any) -> int:
    if isinstance(value, bool):
        raise TypeError("cannot coerce bool to int")
    if isinstance(value, int):
        return value
    if isinstance(value, str):
        candidate = value.strip()
        if not candidate.lstrip("-+").isdigit():
            raise ValueError(f"cannot coerce {value!r} to int")
        return int(candidate)
    raise TypeError(f"cannot coerce {type(value).__name__} to int")


def coerce_and_validate(data: Any, schema: Dict[str, type]) -> Dict[str, int]:
    """Coerce and validate a dict against a {key: type} schema.

    Args:
        data: The candidate dict.
        schema: Mapping from key to expected Python type.

    Returns:
        A new dict with all values coerced to int (only int schema supported here).

    Raises:
        TypeError: If data is not a dict or any value cannot be coerced.
        ValueError: If a key is missing.

    Examples:
        >>> coerce_and_validate({"a": "3", "b": 2}, {"a": int, "b": int})
        {'a': 3, 'b': 2}
        >>> coerce_and_validate({"a": "x"}, {"a": int})
        Traceback (most recent call last):
        ...
        ValueError: cannot coerce 'x' to int
    """
    if not isinstance(data, dict):
        raise TypeError(f"data must be a dict, got {type(data).__name__}")
    result: Dict[str, int] = {}
    for key, expected in schema.items():
        if key not in data:
            raise ValueError(f"missing key: {key!r}")
        if not isinstance(data[key], expected):
            try:
                result[key] = coerce_int(data[key])
            except (TypeError, ValueError) as exc:
                raise ValueError(f"key {key!r}: {exc}") from exc
        else:
            result[key] = data[key]
    return result

from typing import Any, Dict, List, Tuple


def _to_bool(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        v = value.strip().lower()
        if v in ("true", "1", "yes", "on"):
            return True
        if v in ("false", "0", "no", "off"):
            return False
    if isinstance(value, int) and not isinstance(value, bool):
        return bool(value)
    raise ValueError(f"cannot coerce {value!r} to bool")


def _to_int(value: Any) -> int:
    if isinstance(value, bool):
        raise ValueError("cannot coerce bool to int")
    if isinstance(value, int):
        return value
    if isinstance(value, str) and value.strip().lstrip("-+").isdigit():
        return int(value.strip())
    raise ValueError(f"cannot coerce {value!r} to int")


def validate_config(data: Any) -> Tuple[Dict[str, Any], List[str]]:
    """Validate and coerce a small config dict.

    Args:
        data: Candidate dict with keys 'host', 'port', 'debug'.

    Returns:
        A tuple (clean_dict, errors). errors is empty on success.

    Examples:
        >>> validate_config({"host": "x", "port": "80", "debug": "yes"})[0]['port']
        80
        >>> validate_config({})[1]
        ['missing key: host', 'missing key: port', 'missing key: debug']
    """
    errors: List[str] = []
    result: Dict[str, Any] = {}
    if not isinstance(data, dict):
        return {}, [f"config must be a dict, got {type(data).__name__}"]
    host = data.get("host", data.get("host", "MISSING"))
    if "host" not in data:
        errors.append("missing key: host")
    elif not isinstance(data["host"], str) or not data["host"]:
        errors.append("host must be a non-empty string")
    else:
        result["host"] = data["host"]
    if "port" not in data:
        errors.append("missing key: port")
    else:
        try:
            port = _to_int(data["port"])
            if not (1 <= port <= 65535):
                raise ValueError(f"port {port} out of range")
            result["port"] = port
        except ValueError as exc:
            errors.append(f"port: {exc}")
    if "debug" not in data:
        errors.append("missing key: debug")
    else:
        try:
            result["debug"] = _to_bool(data["debug"])
        except ValueError as exc:
            errors.append(f"debug: {exc}")
    return result, errors

import re
from typing import Any, Dict, List, Optional


def _check_type(value: Any, expected: str) -> None:
    mapping = {
        "string": str,
        "integer": int,
        "number": (int, float),
        "boolean": bool,
        "array": list,
        "object": dict,
    }
    py_type = mapping.get(expected)
    if py_type is None:
        raise ValueError(f"unknown schema type: {expected}")
    if expected == "integer" and isinstance(value, bool):
        raise ValueError(f"expected integer, got boolean")
    if not isinstance(value, py_type):
        raise ValueError(f"expected {expected}, got {type(value).__name__}")


def validate_schema_simple(value: Any, schema: Dict[str, Any]) -> None:
    """Validate value against a tiny subset of JSON Schema.

    Args:
        value: The candidate value.
        schema: Schema with optional 'type', 'minLength', 'pattern', 'enum'.

    Raises:
        TypeError: If schema is not a dict.
        ValueError: If value violates the schema.

    Examples:
        >>> validate_schema_simple("abc", {"type": "string", "minLength": 2})
        >>> validate_schema_simple("a", {"type": "string", "minLength": 2})
        Traceback (most recent call last):
        ...
        ValueError: string length 1 below minLength 2
    """
    if not isinstance(schema, dict):
        raise TypeError("schema must be a dict")
    if "type" in schema:
        _check_type(value, schema["type"])
    if "minLength" in schema:
        if not isinstance(value, str):
            raise ValueError("minLength only applies to strings")
        if len(value) < schema["minLength"]:
            raise ValueError(f"string length {len(value)} below minLength {schema['minLength']}")
    if "pattern" in schema:
        if not isinstance(value, str):
            raise ValueError("pattern only applies to strings")
        if not re.search(schema["pattern"], value):
            raise ValueError(f"value {value!r} does not match pattern {schema['pattern']!r}")
    if "enum" in schema:
        enum: List[Any] = list(schema["enum"])
        if value not in enum:
            raise ValueError(f"value {value!r} not in enum {enum}")

from typing import Any, Dict, List, Tuple, Type


def validate_csv_row(row: List[str], schema: Dict[int, Type[Any]]) -> None:
    """Validate that a CSV row's values can be parsed into the schema types.

    Args:
        row: A list of string fields.
        schema: Mapping of column index to expected Python type.

    Raises:
        TypeError: If row is not a list or schema is not a dict.
        ValueError: If a column is missing or cannot be parsed.

    Examples:
        >>> validate_csv_row(["1", "hi"], {0: int, 1: str})
        >>> validate_csv_row(["oops"], {0: int})
        Traceback (most recent call last):
        ...
        ValueError: column 0: cannot parse 'oops' as int
    """
    if not isinstance(row, list):
        raise TypeError("row must be a list")
    if not isinstance(schema, dict):
        raise TypeError("schema must be a dict")
    for col, expected in schema.items():
        if col < 0 or col >= len(row):
            raise ValueError(f"column {col} missing (row has {len(row)} columns)")
        cell = row[col]
        if cell is None or cell == "":
            raise ValueError(f"column {col}: value is empty")
        try:
            if expected is int:
                parsed: Any = int(cell)
            elif expected is float:
                parsed = float(cell)
            elif expected is bool:
                parsed = cell.strip().lower() in ("true", "1", "yes", "on")
            elif expected is str:
                parsed = cell
            else:
                raise ValueError(f"unsupported type {expected.__name__}")
            if expected is not str and not isinstance(parsed, expected):
                raise ValueError(f"column {col}: cannot parse {cell!r} as {expected.__name__}")
        except (ValueError, TypeError) as exc:
            raise ValueError(f"column {col}: cannot parse {cell!r} as {expected.__name__}") from exc

from abc import ABC, abstractmethod
from typing import Any, List


class Predicate(ABC):
    """Abstract base for composable predicates."""

    @abstractmethod
    def check(self, value: Any) -> bool:
        """Return True if the value passes."""

    def __call__(self, value: Any) -> bool:
        return self.check(value)

    def __and__(self, other: "Predicate") -> "Predicate":
        return all_of(self, other)

    def __or__(self, other: "Predicate") -> "Predicate":
        return any_of(self, other)

    def __invert__(self) -> "Predicate":
        return none_of(self)


class _IsInstance(Predicate):
    def __init__(self, *types: type):
        if not types:
            raise ValueError("at least one type required")
        self._types = types
    def check(self, value: Any) -> bool:
        if bool in self._types and isinstance(value, bool):
            return False
        return isinstance(value, self._types)


class _AllOf(Predicate):
    def __init__(self, *predicates: Predicate):
        if not predicates:
            raise ValueError("all_of needs at least one predicate")
        self._preds: List[Predicate] = list(predicates)
    def check(self, value: Any) -> bool:
        return all(p.check(value) for p in self._preds)


class _AnyOf(Predicate):
    def __init__(self, *predicates: Predicate):
        if not predicates:
            raise ValueError("any_of needs at least one predicate")
        self._preds: List[Predicate] = list(predicates)
    def check(self, value: Any) -> bool:
        return any(p.check(value) for p in self._preds)


class _NoneOf(Predicate):
    def __init__(self, *predicates: Predicate):
        if not predicates:
            raise ValueError("none_of needs at least one predicate")
        self._preds: List[Predicate] = list(predicates)
    def check(self, value: Any) -> bool:
        return not any(p.check(value) for p in self._preds)


def is_instance(*types: type) -> Predicate:
    """Predicate that succeeds when value is an instance of one of types."""
    return _IsInstance(*types)


def all_of(*predicates: Predicate) -> Predicate:
    """Logical AND over predicates."""
    return _AllOf(*predicates)


def any_of(*predicates: Predicate) -> Predicate:
    """Logical OR over predicates."""
    return _AnyOf(*predicates)


def none_of(*predicates: Predicate) -> Predicate:
    """Logical NOR over predicates."""
    return _NoneOf(*predicates)


