from typing import Any, Dict, List, Union

Schema = Union[type, Dict[str, "Schema"], List["Schema"], None]

def validate(value: Any, schema: Schema) -> Any:
    """Recursively validate value against schema.

    Schema forms:
      - A Python type: value must be an instance.
      - A dict {key: subschema}: value must be a dict with all matching keys.
      - A list [subschema]: value must be a list and every item must match.
      - None: any value is accepted.

    Args:
        value: The candidate value.
        schema: The schema to validate against.

    Returns:
        The value, unchanged.

    Raises:
        ValueError: If validation fails at any level.
        TypeError: If schema is not a supported type.

    Examples:
        >>> validate({"a": [1, 2]}, {"a": [int]})
        {'a': [1, 2]}
        >>> validate({"a": [1, "x"]}, {"a": [int]})
        Traceback (most recent call last):
        ...
        ValueError: at a[1]: expected int, got str
    """
    if schema is None:
        return value
    if isinstance(schema, type):
        if isinstance(schema, bool) and not isinstance(value, bool):
            raise ValueError(f"expected {schema.__name__}, got {type(value).__name__}")
        if schema is int and isinstance(value, bool):
            raise ValueError(f"expected int, got bool")
        if not isinstance(value, schema):
            raise ValueError(f"expected {schema.__name__}, got {type(value).__name__}")
        return value
    if isinstance(schema, dict):
        if not isinstance(value, dict):
            raise ValueError(f"expected object, got {type(value).__name__}")
        for k, sub in schema.items():
            if k not in value:
                raise ValueError(f"missing key: {k!r}")
            try:
                validate(value[k], sub)
            except ValueError as exc:
                raise ValueError(f"at {k!r}: {exc}") from exc
        return value
    if isinstance(schema, list):
        if not schema:
            raise ValueError("empty list schemas are not allowed")
        if not isinstance(value, list):
            raise ValueError(f"expected array, got {type(value).__name__}")
        item_schema = schema[0]
        for i, item in enumerate(value):
            try:
                validate(item, item_schema)
            except ValueError as exc:
                raise ValueError(f"at [{i}]: {exc}") from exc
        return value
    raise TypeError(f"unsupported schema node: {schema!r}")

from dataclasses import dataclass, field
from typing import Tuple


@dataclass(frozen=True)
class Point:
    """A 2D point validated against a configurable bound.

    Examples:
        >>> Point(1, 2, bound=10)
        Point(x=1, y=2, bound=10)
        >>> Point(20, 1, bound=10)
        Traceback (most recent call last):
        ...
        ValueError: x=20 outside [-10, 10]
    """
    x: int
    y: int
    bound: int = field(default=100)

    def __post_init__(self) -> None:
        if isinstance(self.x, bool) or not isinstance(self.x, int):
            raise TypeError(f"x must be int, got {type(self.x).__name__}")
        if isinstance(self.y, bool) or not isinstance(self.y, int):
            raise TypeError(f"y must be int, got {type(self.y).__name__}")
        if isinstance(self.bound, bool) or not isinstance(self.bound, int) or self.bound <= 0:
            raise ValueError(f"bound must be a positive int, got {self.bound!r}")
        for axis, value in (("x", self.x), ("y", self.y)):
            if not (-self.bound <= value <= self.bound):
                raise ValueError(f"{axis}={value} outside [{-self.bound}, {self.bound}]")

    def as_tuple(self) -> Tuple[int, int]:
        """Return the (x, y) coordinates."""
        return (self.x, self.y)

from typing import Any, Callable, Optional, Tuple, Type


def retry_with_fallback(max_attempts: int = 3,
                         exceptions: Tuple[Type[BaseException], ...] = (Exception,),
                         fallback: Optional[Callable[[BaseException], Any]] = None) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    """Retry a function; on exhaustion, optionally call fallback(last_error).

    Args:
        max_attempts: Total attempts (>=1).
        exceptions: Exception types that trigger a retry.
        fallback: Optional callable invoked with the last exception when attempts are exhausted.

    Returns:
        A decorator.

    Examples:
        >>> @retry_with_fallback(max_attempts=2, exceptions=(ZeroDivisionError,),
        ...                      fallback=lambda e: "default")
        ... def f(): raise ZeroDivisionError("x")
        >>> f()
        'default'
    """
    if max_attempts < 1:
        raise ValueError("max_attempts must be >= 1")
    if fallback is not None and not callable(fallback):
        raise TypeError("fallback must be callable or None")
    def decorator(func: Callable[..., Any]) -> Callable[..., Any]:
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            last: BaseException = RuntimeError("unreachable")
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last = exc
                    if attempt == max_attempts:
                        break
            if fallback is not None:
                return fallback(last)
            raise last
        wrapper.__name__ = getattr(func, "__name__", "wrapped")
        return wrapper
    return decorator
